/* Minimal config.h for the vendored niftilib sources.
 *
 * Upstream znzlib.h does `#include "config.h"` and expects the enclosing
 * project to supply one.  In libminc that file is generated by its CMake
 * configure step; vendoring the sources here means we must provide it
 * ourselves.  Only the two symbols below are actually consulted by
 * znzlib.h / znzlib.c / nifti1_io.c.
 */
#ifndef NR_NIFTI_CONFIG_H
#define NR_NIFTI_CONFIG_H

#define HAVE_ZLIB   1
#define HAVE_FDOPEN 1

#endif /* NR_NIFTI_CONFIG_H */
